insert into public.concept (id, kicker_nl, kicker_en, heading_nl, heading_en, body1_nl, body1_en, body2_nl, body2_en) values
  (1, 'Het concept', 'The concept', 'Een plek waar je blijft hangen', 'A place where you linger', 'Café Faim is een plek waar je samenkomt, waar je blijft hangen, waar je even ontsnapt aan de drukte en gewoon geniet. Een kleine pauze in je dag — met de geur van vers gebakken lekkers om je heen.', 'Café Faim is a place where you come together, where you linger, where you escape the rush for a moment and simply enjoy. A small pause in your day — surrounded by the smell of freshly baked treats.', 'Alles wat je hier proeft wordt met liefde en aandacht gemaakt. Denk aan loaded cookies die rijk gevuld zijn en precies goed in elke bite, romige cheesecakes, gepersonaliseerde taarten en speelse cakepops die eruitzien als kleine cadeautjes.', 'Everything you taste here is made with love and attention. Think loaded cookies that are richly filled and just right in every bite, creamy cheesecakes, personalised cakes and playful cakepops that look like little gifts.');
